+#!/usr/bin/env node
+import { buildSite } from './generator.js';
+
+function usage(): string {
+  return 'Usage: ssg build [--content <dir>] [--output <dir>]';
+}
+
+function parseArgs(args: string[]): { contentDir?: string; outputDir?: string } {
+  const options: { contentDir?: string; outputDir?: string } = {};
+  for (let index = 0; index < args.length; index += 1) {
+    const value = args[index];
+    if (value === '--content' || value === '--output') {
+      const path = args[++index];
+      if (!path) throw new Error(`Missing value for ${value}`);
+      if (value === '--content') options.contentDir = path;
+      else options.outputDir = path;
+    } else {
+      throw new Error(`Unknown option: ${value}`);
+    }
+  }
+  return options;
+}
+
+async function main(): Promise<void> {
+  const [command, ...args] = process.argv.slice(2);
+  if (command !== 'build') throw new Error(usage());
+  const pages = await buildSite(parseArgs(args));
+  process.stdout.write(`Generated ${pages.length} page(s).\n`);
+}
+
+main().catch((error: unknown) => {
+  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
+  process.exitCode = 1;
+});

